"""Read-only post-deletion checks, recording full subprocess evidence on stdout."""
import ast
from bisect import bisect_right
from collections import Counter
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile
import tomllib

ROOT = Path.cwd()
MAIN = Path('/home/linhao/Toolchain/development/LogAnalysisSkill')
D = 'docs/clang-fix-campaign/'
P = D+'dev_memory/stage14_p49_terminal_batch/a0-evidence/phase2/'
GATE = MAIN/P/'gate-package'
EX = MAIN/P/'execution'
sys.path.insert(0,str(ROOT/D/'tools'))
from terminal_entry_observation import enumerate_entries

def run(argv, env=None, cwd=None):
    p=subprocess.run(argv,cwd=cwd or ROOT,env=env,capture_output=True,text=True,timeout=180)
    print(json.dumps(dict(argv=argv,cwd=str(cwd or ROOT),exit=p.returncode,stdout=p.stdout,stderr=p.stderr),ensure_ascii=False),flush=True)
    assert p.returncode==0,argv
    return p.stdout

def tracked():
    return subprocess.check_output(['git','ls-tree','-r','--name-only','HEAD'],text=True).splitlines()

def entries():
    current=enumerate_entries(ROOT)
    original=json.loads((MAIN/P/'../B-5-entries.json').read_text())
    assert current['independent_enumeration']==original['independent_enumeration']
    for row in current['entries']:
        env=dict(os.environ)
        env['PYTHONPATH']=os.pathsep.join(str(ROOT/p) for p in current['packaging'][row['context']]['roots'])
        env.pop('MYPYPATH',None)
        print('ENTRY '+row['entry_id'],flush=True)
        run(row['argv'],env)
    print(f"SMOKE entries={len(current['entries'])} passed={len(current['entries'])}")

def modules():
    config=tomllib.loads((ROOT/'pyproject.toml').read_text())
    roots=config['tool']['setuptools']['packages']['find']['where']
    names=[]
    for p in tracked():
        if not p.endswith('.py') or p.startswith('release-v1.4.0/'):
            continue
        found=False
        for base in roots:
            if p.startswith(base+'/'):
                name=p[len(base)+1:-3].replace('/','.')
                if name.endswith('.__init__'):
                    name=name[:-9]
                names.append((p,name))
                found=True
                break
        if not found:
            names.append((p,None))
    assert len({n for _,n in names if n})==sum(n is not None for _,n in names)
    for path,name in names:
        print('IMPORT '+path,flush=True)
        if name:
            program='import importlib; importlib.import_module('+repr(name)+')'
        else:
            program=("import importlib.util,sys; from pathlib import Path; "
                     f"p=Path({str(ROOT)!r})/{path!r}; sys.path.insert(0,str(p.parent)); "
                     "s=importlib.util.spec_from_file_location('_post_delete_probe',p); "
                     "m=importlib.util.module_from_spec(s); sys.modules[s.name]=m; s.loader.exec_module(m)")
        run([sys.executable,'-c',program])
    print(f'IMPORT_ALL modules={len(names)} passed={len(names)}')

def residual(group):
    inventory=json.loads((GATE/'deletion-inventory.json').read_text())['entries']
    groups=json.loads((GATE/'commit-groups.json').read_text())
    if isinstance(groups,dict):
        groups=groups['groups']
    hosts={r['host'] for r in groups if r['group']<=group}
    inventory=[r for r in inventory if r['path'] in hosts]
    keys=json.loads((EX/'historical-keys.approved.json').read_text())
    # Original three relocation keys are exact AST tuple entries, not file exemptions.
    bridge=D+'tools/table_audit_bridge.py'
    tree=ast.parse((ROOT/bridge).read_text())
    relocation=next(n for n in tree.body if isinstance(n,ast.AnnAssign) and isinstance(n.target,ast.Name) and n.target.id=='BUILD_VERIFY_RELOCATIONS')
    key_sites={(bridge,n.elts[0].lineno) for n in relocation.value.keys if ast.literal_eval(n)[0]=='ci_triage/verify/workspace.py'}
    def forms(row):
        module=row['module']
        if row['scope']=='MODULE':
            yield 'DOT',module
        else:
            for binding in row['bindings']:
                yield 'DOT',module+'.'+binding['name']
        yield 'SOURCE_PATH',row['path'].split('/scripts/',1)[1]
        if row['scope']=='MODULE':
            yield 'PACKAGE_PATH',module.replace('.','/')+'/'
            parent,_,name=module.rpartition('.')
            yield 'SPLIT',(parent,name)
        for binding in row['bindings']:
            yield 'SPLIT',(module,binding['name'])
    hits=[]
    binary=[]
    for path in tracked():
        raw=(ROOT/path).read_bytes()
        try:
            assert b'\0' not in raw
            text=raw.decode()
        except (UnicodeDecodeError,AssertionError):
            binary.append(path)
            continue
        lines=text.splitlines()
        starts=[0]+[m.end() for m in re.finditer('\n',text)]
        for row in inventory:
            for form,value in forms(row):
                if form=='SPLIT':
                    mod,name=value
                    pattern=r'\bfrom\s+'+re.escape(mod)+r'\s+import\s+(?:\([^)]*\)|[^\n;]+)'
                else:
                    pattern=r'(?<![A-Za-z0-9_.])'+re.escape(value)+r'(?![A-Za-z0-9_])'
                for match in re.finditer(pattern,text):
                    if form=='SPLIT' and not re.search(r'(?<![\w.])'+re.escape(name)+r'\b',re.split(r'\bimport\s+',match[0],maxsplit=1)[1]):
                        continue
                    line=bisect_right(starts,match.start())
                    source=lines[line-1]
                    category='OTHER'
                    if path.startswith('release-v1.4.0/'):
                        category='RELEASE'
                    elif path.startswith(D) and not(path.startswith(D+'tools/') and path.endswith('.py')):
                        category='HISTORICAL'
                    elif (path,line) in key_sites or any(k['file']==path and k.get('exact_line')==source and k['value'] in source for k in keys):
                        category='HISTORICAL_KEY'
                    hits.append(dict(candidate=row['path'],path=path,line=line,form=form,value=value,source=source,classification=category))
    print(json.dumps(dict(group=group,hosts=sorted(hosts),hits=hits,binary=binary,counts=dict(Counter(r['classification'] for r in hits))),ensure_ascii=False,indent=2))
    bad=[r for r in hits if r['classification']=='OTHER']
    print(f'RESIDUAL hits={len(hits)} OTHER={len(bad)}')
    assert not bad,bad

def nodeids(group):
    def parse(path):
        result={}
        for line in path.read_text().splitlines():
            m=re.match(r'.*?(tests/.+) (PASSED|SKIPPED|FAILED|ERROR)(?:\s+\[|$)',line)
            if m:
                assert m[1] not in result
                result[m[1]]=m[2]
        return result
    base=parse(EX/'HASH08/full-tests.log')
    now=parse(EX/group/'full-tests.log')
    approved={r['nodeid'] for r in json.loads((GATE/'proposed-test-deletions.json').read_text())['entries']}
    lost=base.keys()-now.keys()
    changed={k:(base[k],now[k]) for k in base.keys() & now.keys() if base[k]!=now[k]}
    print(json.dumps(dict(base=len(base),current=len(now),lost=sorted(lost),changed=changed,added=sorted(now.keys()-base.keys()),counts=dict(Counter(now.values()))),indent=2))
    assert lost<=approved and not changed and set(now.values())<={'PASSED','SKIPPED'}

def packaging():
    with tempfile.TemporaryDirectory(prefix='p49-wheel-') as tmp:
        run([sys.executable,'-m','pip','wheel','--no-deps','--wheel-dir',tmp,'.'])
        wheel=next(Path(tmp).glob('*.whl'))
        print('WHEEL_SHA256 '+hashlib.sha256(wheel.read_bytes()).hexdigest())
        envpath=Path(tmp)/'install'
        run([sys.executable,'-m','venv','--without-pip',str(envpath)])
        python=str(envpath/'bin/python')
        run([sys.executable,'-m','pip','--python',python,'install',str(wheel)])
        config=tomllib.loads((ROOT/'pyproject.toml').read_text())
        scripts=config['project'].get('scripts',{})
        env=dict(os.environ)
        env.pop('PYTHONPATH',None)
        env.pop('MYPYPATH',None)
        for name in scripts:
            run([str(envpath/'bin'/name),'--help'],env,cwd=Path(tmp))
        # No declared console scripts: also smoke installed package -m entries.
        entries=enumerate_entries(ROOT)['entries']
        modules=[r for r in entries if r['context']=='' and r['kind']=='PACKAGE_MAIN']
        for row in modules:
            run([python,'-m',row['target'],'--help'],env,cwd=Path(tmp))
        print(f'PACKAGING wheel=OK install=OK console_scripts={len(scripts)} installed_module_entries={len(modules)}')

command=sys.argv[1]
if command=='smoke': entries()
elif command=='import-all': modules()
elif command=='residual': residual(sys.argv[2])
elif command=='nodeids': nodeids(sys.argv[2])
elif command=='packaging': packaging()
else: raise ValueError(command)
